import{_ as a,o as n,a as p,b as c}from"./app.C41L12d5.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"Aclnn算子工程化开发","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/overview"},{"text":"附录","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/appendix/appendix"},{"text":"CMake函数参考","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/appendix/cmake_function_reference"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/appendix/cmake_function_reference.md","filePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/appendix/cmake_function_reference.md","outlineHeaders":[{"level":2,"title":"概述","slug":"概述","link":"#概述"},{"level":2,"title":"函数一览","slug":"函数一览","link":"#函数一览"},{"level":2,"title":"Package类函数","slug":"Package类函数","link":"#Package类函数"},{"level":3,"title":"npu_op_package","slug":"npu_op_package","link":"#npu_op_package"},{"level":3,"title":"npu_op_package_add","slug":"npu_op_package_add","link":"#npu_op_package_add"},{"level":2,"title":"Library类函数","slug":"Library类函数","link":"#Library类函数"},{"level":3,"title":"npu_op_library","slug":"npu_op_library","link":"#npu_op_library"},{"level":3,"title":"npu_op_kernel_library","slug":"npu_op_kernel_library","link":"#npu_op_kernel_library"},{"level":3,"title":"npu_op_kernel_options","slug":"npu_op_kernel_options","link":"#npu_op_kernel_options"},{"level":3,"title":"npu_op_kernel_sources","slug":"npu_op_kernel_sources","link":"#npu_op_kernel_sources"},{"level":3,"title":"npu_op_device_tiling_library","slug":"npu_op_device_tiling_library","link":"#npu_op_device_tiling_library"},{"level":2,"title":"其他","slug":"其他","link":"#其他"},{"level":3,"title":"npu_op_code_gen","slug":"npu_op_code_gen","link":"#npu_op_code_gen"},{"level":2,"title":"相关文档","slug":"相关文档","link":"#相关文档"}],"lastUpdated":1788139350000}'),l={name:"guide/programming_guide/advanced_programming/aclnn_operator_development/appendix/cmake_function_reference.md"};function e(t,s,o,d,i,_){return n(),p("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>CMake函数参考</h1><p>本文是参考内容，整理算子工程编译过程涉及的CMake函数接口，供需要深入了解编译机制的高级开发者查阅。</p><h2 id="概述">概述<a class="header-anchor" href="#概述">​</a></h2><p>使用msOpGen工具创建算子工程时，相关编译脚本被固化在本地。为便于开发者直接使用算子工程对外提供的cmake函数接口而无需频繁重建工程，CANN软件包中将算子工程的cmake脚本打包，开发者可通过<code>find_package</code>查找对应的cmake modules包来使用这些函数。</p><p>本文说明算子工程编译过程中使用的8个CMake函数，按用途分为<strong>Package类</strong>、<strong>Library类</strong>、<strong>其他</strong>三类。</p><h2 id="函数一览">函数一览<a class="header-anchor" href="#函数一览">​</a></h2><table><thead><tr><th>分类</th><th>函数</th><th>功能</th></tr></thead><tbody><tr><td>Package</td><td><code>npu_op_package</code></td><td>创建一个package。</td></tr><tr><td>Package</td><td><code>npu_op_package_add</code></td><td>将目标或文件添加到package中。</td></tr><tr><td>Library</td><td><code>npu_op_library</code></td><td>创建Host侧库。</td></tr><tr><td>Library</td><td><code>npu_op_kernel_library</code></td><td>创建核函数（Kernel）侧库。</td></tr><tr><td>Library</td><td><code>npu_op_kernel_options</code></td><td>添加核函数（Kernel）目标编译选项。</td></tr><tr><td>Library</td><td><code>npu_op_kernel_sources</code></td><td>描述核函数（Kernel）目标的源码信息。</td></tr><tr><td>Library</td><td><code>npu_op_device_tiling_library</code></td><td>创建Device侧Tiling库。</td></tr><tr><td>其他</td><td><code>npu_op_code_gen</code></td><td>执行代码生成过程，生成aclnn单算子调用代码和入图所需的原型定义代码。</td></tr></tbody></table><hr><h2 id="Package类函数">Package类函数<a class="header-anchor" href="#Package类函数">​</a></h2><h3 id="npu_op_package">npu_op_package<a class="header-anchor" href="#npu_op_package">​</a></h3><p>创建一个package。</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_package</span><span class="p">(</span><span class="s">&lt;package_name&gt;</span><span class="w"> </span><span class="s">TYPE</span><span class="w"> </span><span class="s">&lt;type&gt;</span><span class="w"> </span><span class="s">[CONFIG]</span><span class="w"> </span><span class="s">[ENABLE_SOURCE_PACKAGE</span><span class="w"> </span><span class="s">&lt;value&gt;]</span><span class="w"> </span><span class="s">[ENABLE_BINARY_PACKAGE</span><span class="w"> </span><span class="s">&lt;value&gt;]</span><span class="w"> </span><span class="s">[INSTALL_PATH</span><span class="w"> </span><span class="s">&lt;path&gt;]</span><span class="p">)</span>
</code></pre></div><p><strong>参数说明：</strong></p><ul><li><code>&lt;package_name&gt;</code>（必选）：package的名称。</li><li><code>TYPE &lt;type&gt;</code>（必选）：package的类型，取值为<code>RUN</code>、<code>SHARED</code>、<code>STATIC</code>。分别对应算子run包形式、算子动态库形式与算子静态库形式。</li><li><code>[CONFIG]</code>（可选）：用于配置package的内容和安装位置。 <ul><li><code>[ENABLE_SOURCE_PACKAGE &lt;value&gt;]</code>（可选）：是否将源码打包到package中，默认为True。</li><li><code>[ENABLE_BINARY_PACKAGE &lt;value&gt;]</code>（可选）：是否将二进制文件打包到package中，默认为True。</li><li><code>[INSTALL_PATH &lt;path&gt;]</code>（可选）：指定包的安装路径，默认为<code>CMAKE_BINARY_DIR</code>。</li><li><code>[ENABLE_CPACK &lt;value&gt;]</code>（可选）：是否打包，默认为True。对于用户需要定制打包的场景，可以设置为False，配置为False的情况下直接在<code>&lt;path&gt;</code>路径下生成编译产物，不会打包为run包。</li></ul></li></ul><p><strong>示例：</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">set</span><span class="p">(</span><span class="s">package_name</span><span class="w"> </span><span class="o">\${</span><span class="nv">vendor_name</span><span class="o">}</span><span class="p">)</span>
<span class="nb">npu_op_package</span><span class="p">(</span><span class="o">\${</span><span class="nv">package_name</span><span class="o">}</span><span class="w">                     </span><span class="c"># package name</span>
<span class="w">    </span><span class="s">TYPE</span><span class="w"> </span><span class="s">RUN</span><span class="w">                                       </span><span class="c">#指定编译产物形态，[RUN|STATIC|SHARED]</span>
<span class="w">    </span><span class="s">CONFIG</span>
<span class="w">        </span><span class="s">ENABLE_SOURCE_PACKAGE</span><span class="w"> </span><span class="s">True</span><span class="w">                 </span><span class="c">#是否将源码打包到package中</span>
<span class="w">        </span><span class="s">ENABLE_BINARY_PACKAGE</span><span class="w"> </span><span class="s">True</span><span class="w">                 </span><span class="c">#是否编译核函数（Kernel）二进制</span>
<span class="w">        </span><span class="s">INSTALL_PATH</span><span class="w"> </span><span class="o">\${</span><span class="nv">CMAKE_BINARY_DIR</span><span class="o">}</span><span class="s">/</span><span class="w">          </span><span class="c"># package的安装位置</span>
<span class="p">)</span>
</code></pre></div><h3 id="npu_op_package_add">npu_op_package_add<a class="header-anchor" href="#npu_op_package_add">​</a></h3><p>将目标或文件添加到package中。</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c"># 添加目标</span>
<span class="nb">npu_op_package_add</span><span class="p">(</span><span class="s">&lt;package_name&gt;</span><span class="w"> </span><span class="s">LIBRARY</span><span class="w"> </span><span class="s">&lt;target_name1&gt;</span><span class="w"> </span><span class="s">[&lt;target_name2&gt;...]</span><span class="w"> </span><span class="p">)</span>
<span class="c"># 添加文件，仅给run包模式使用</span>
<span class="nb">npu_op_package_add</span><span class="p">(</span><span class="s">&lt;package_name&gt;</span><span class="w"> </span><span class="s">FILES</span><span class="w"> </span><span class="s">&lt;file_name1&gt;</span><span class="w"> </span><span class="s">[&lt;file_name2&gt;...]</span><span class="w"> </span><span class="s">[TYPE</span><span class="w"> </span><span class="s">&lt;target_type&gt;]</span><span class="w"> </span><span class="s">[PACKAGE_PATH</span><span class="w"> </span><span class="s">&lt;pkg_path&gt;]</span><span class="p">)</span>
</code></pre></div><p><strong>参数说明：</strong></p><ul><li><code>&lt;package_name&gt;</code>（必选）：package的名称。</li><li><code>LIBRARY</code>（必选）：指定需要添加到package中的目标名称。 <ul><li><code>&lt;target_name1&gt; [&lt;target_name2&gt;...]</code>（必选）：目标名称列表。</li></ul></li><li><code>FILES</code>（必选）：指定需要添加到package中的文件名称。 <ul><li><code>&lt;file_name1&gt; [&lt;file_name2&gt;...]</code>（必选）：文件名称列表。</li></ul></li><li><code>[TYPE &lt;target_type&gt;]</code>（可选）：指定文件类型，将文件安装到对应的目录中，取值为<code>ACLNN</code>、<code>GRAPH</code>。配置为<code>ACLNN</code>，会将文件打包至run包目录下aclnn单算子调用头文件所在目录；配置为<code>GRAPH</code>，会将文件打包至run包目录下入图原型定义头文件目录下。</li><li><code>[PACKAGE_PATH &lt;pkg_path&gt;]</code>（可选）：指定文件在包中的相对路径位置。<code>TYPE</code>和<code>PACKAGE_PATH</code>参数互斥，即只能选择其中一个进行配置。</li></ul><p><strong>示例：</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c"># 添加Host侧相关library</span>
<span class="nb">npu_op_package_add</span><span class="p">(</span><span class="o">\${</span><span class="nv">package_name</span><span class="o">}</span>
<span class="w">    </span><span class="s">LIBRARY</span>
<span class="w">        </span><span class="s">cust_optiling</span>
<span class="w">        </span><span class="s">cust_opapi</span>
<span class="w">        </span><span class="s">cust_op_proto</span>
<span class="p">)</span>

<span class="c"># 添加核函数（Kernel）侧相关library</span>
<span class="nb">npu_op_package_add</span><span class="p">(</span><span class="o">\${</span><span class="nv">package_name</span><span class="o">}</span>
<span class="w">    </span><span class="s">LIBRARY</span><span class="w"> </span><span class="s">ascendc_kernels</span>
<span class="p">)</span>
</code></pre></div><hr><h2 id="Library类函数">Library类函数<a class="header-anchor" href="#Library类函数">​</a></h2><h3 id="npu_op_library">npu_op_library<a class="header-anchor" href="#npu_op_library">​</a></h3><p>创建Host侧库。</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_library</span><span class="p">(</span><span class="s">&lt;library_name&gt;</span><span class="w"> </span><span class="s">TYPE</span><span class="w"> </span><span class="s">&lt;library_type&gt;</span><span class="w"> </span><span class="s">&lt;files&gt;</span><span class="p">)</span>
</code></pre></div><p><strong>参数说明：</strong></p><ul><li><code>&lt;library_name&gt;</code>（必选）：Host侧库的名称。</li><li><code>TYPE &lt;library_type&gt;</code>（必选）：Host库的类型，可选值为<code>TILING</code>、<code>ACLNN</code>、<code>GRAPH</code>、<code>TF_PLUGIN</code>、<code>ONNX_PLUGIN</code>。 <ul><li><code>TILING</code>：Tiling相关库。</li><li><code>ACLNN</code>：aclnn单算子调用库。</li><li><code>GRAPH</code>：算子入图所需的算子原型库。</li><li><code>TF_PLUGIN</code>：TensorFlow框架适配相关库。</li><li><code>ONNX_PLUGIN</code>：ONNX框架适配相关库。</li></ul></li><li><code>&lt;files&gt;</code>（必选）：设置参与编译的源文件。</li></ul><p><strong>示例：</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c"># 单算子调用场景，编译aclnn单算子调用库</span>
<span class="nb">file</span><span class="p">(</span><span class="s">GLOB</span><span class="w"> </span><span class="s">autogen_aclnn_src</span><span class="w"> </span><span class="o">\${</span><span class="nv">ASCEND_AUTOGEN_PATH</span><span class="o">}</span><span class="s">/aclnn_*.cpp</span><span class="p">)</span>
<span class="nb">set_source_files_properties</span><span class="p">(</span><span class="o">\${</span><span class="nv">autogen_aclnn_src</span><span class="o">}</span><span class="w"> </span><span class="s">PROPERTIES</span><span class="w"> </span><span class="s">GENERATED</span><span class="w"> </span><span class="s">TRUE</span><span class="p">)</span>
<span class="nb">npu_op_library</span><span class="p">(</span><span class="s">cust_opapi</span><span class="w"> </span><span class="s">ACLNN</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">autogen_aclnn_src</span><span class="o">}</span>
<span class="p">)</span>

<span class="c"># 算子入图场景，编译算子入图所需的算子原型库</span>
<span class="nb">file</span><span class="p">(</span><span class="s">GLOB</span><span class="w"> </span><span class="s">proto_src</span><span class="w"> </span><span class="o">\${</span><span class="nv">ASCEND_AUTOGEN_PATH</span><span class="o">}</span><span class="s">/op_proto.cc</span><span class="p">)</span>
<span class="nb">set_source_files_properties</span><span class="p">(</span><span class="o">\${</span><span class="nv">proto_src</span><span class="o">}</span><span class="w"> </span><span class="s">PROPERTIES</span><span class="w"> </span><span class="s">GENERATED</span><span class="w"> </span><span class="s">TRUE</span><span class="p">)</span>
<span class="nb">npu_op_library</span><span class="p">(</span><span class="s">cust_op_proto</span><span class="w"> </span><span class="s">GRAPH</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">ops_srcs</span><span class="o">}</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">proto_src</span><span class="o">}</span>
<span class="p">)</span>

<span class="c"># 编译Tiling相关库</span>
<span class="nb">file</span><span class="p">(</span><span class="s">GLOB</span><span class="w"> </span><span class="s">fallback_src</span><span class="w"> </span><span class="o">\${</span><span class="nv">ASCEND_AUTOGEN_PATH</span><span class="o">}</span><span class="s">/fallback_*.cpp</span><span class="p">)</span>
<span class="nb">set_source_files_properties</span><span class="p">(</span><span class="o">\${</span><span class="nv">fallback_src</span><span class="o">}</span><span class="w"> </span><span class="s">PROPERTIES</span><span class="w"> </span><span class="s">GENERATED</span><span class="w"> </span><span class="s">TRUE</span><span class="p">)</span>
<span class="nb">npu_op_library</span><span class="p">(</span><span class="s">cust_optiling</span><span class="w"> </span><span class="s">TILING</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">ops_srcs</span><span class="o">}</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">fallback_src</span><span class="o">}</span>
<span class="p">)</span>
</code></pre></div><h3 id="npu_op_kernel_library">npu_op_kernel_library<a class="header-anchor" href="#npu_op_kernel_library">​</a></h3><p>创建核函数（Kernel）侧库。</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_kernel_library</span><span class="p">(</span><span class="s">&lt;target_name&gt;</span><span class="w"> </span><span class="s">SRC_BASE</span><span class="w"> </span><span class="s">&lt;path&gt;</span><span class="w"> </span><span class="s">TILING_LIBRARY</span><span class="w"> </span><span class="s">&lt;tiling_target&gt;</span><span class="p">)</span>
</code></pre></div><p><strong>参数说明：</strong></p><ul><li><code>&lt;target_name&gt;</code>（必选）：目标的名称。</li><li><code>SRC_BASE &lt;path&gt;</code>（必选）：指定核函数（Kernel）源码的base目录，要求配置绝对路径。例如示例中的<code>op_kernel</code>目录的绝对路径。</li><li><code>TILING_LIBRARY &lt;tiling_target&gt;</code>（必选）：指定依赖的Tiling目标。</li></ul><p><strong>示例：</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_kernel_library</span><span class="p">(</span><span class="s">ascendc_kernels</span>
<span class="w">    </span><span class="s">SRC_BASE</span><span class="w"> </span><span class="o">\${</span><span class="nv">CMAKE_SOURCE_DIR</span><span class="o">}</span><span class="s">/op_kernel/</span>
<span class="w">    </span><span class="s">TILING_LIBRARY</span><span class="w"> </span><span class="s">cust_optiling</span>
<span class="p">)</span>
</code></pre></div><h3 id="npu_op_kernel_options">npu_op_kernel_options<a class="header-anchor" href="#npu_op_kernel_options">​</a></h3><p>添加核函数（Kernel）目标编译选项。</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_kernel_options</span><span class="p">(</span><span class="s">&lt;target_name&gt;</span><span class="w"> </span><span class="s">&lt;op_type&gt;</span><span class="w"> </span><span class="s">[COMPUTE_UNIT</span><span class="w"> </span><span class="s">&lt;soc_version&gt;...</span><span class="w"> </span><span class="s">|</span><span class="w"> </span><span class="s">SOC_SERIES</span><span class="w"> </span><span class="s">&lt;series&gt;...]</span><span class="w"> </span><span class="s">OPTIONS</span><span class="w"> </span><span class="s">…</span><span class="p">)</span>
</code></pre></div><p><strong>参数说明：</strong></p><ul><li><code>&lt;target_name&gt;</code>（必选）：目标的名称。</li><li><code>&lt;op_type&gt;</code>（必选）：定义配置生效的范围，取值为<code>ALL</code>、<code>OP_TYPE</code>。<code>ALL</code>表示对所有算子生效，<code>OP_TYPE</code>表示对特定算子生效。</li><li><code>[COMPUTE_UNIT &lt;soc_version&gt;...]</code>（可选）：用于设置算子在具体AI处理器型号上的编译选项，不填写该选项时默认对所有型号生效。与<code>SOC_SERIES</code>不能同时使用。</li><li><code>[SOC_SERIES &lt;series&gt;...]</code>（可选）：用于按AI处理器系列设置编译选项。输入不区分大小写；与<code>COMPUTE_UNIT</code>不能同时使用。<code>SOC_SERIES</code>关键字后必须提供至少一个值；同一次调用同时提供<code>SOC_SERIES</code>和<code>COMPUTE_UNIT</code>，或只提供<code>SOC_SERIES</code>关键字不提供值，CMake配置阶段会报错。</li></ul><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明 其中，AI处理器型号<code>soc_version</code>请通过以下方式获取：</p><div data-filter="910b,910,310p,310b"><ul><li><p>针对如下产品：在安装AI处理器的服务器执行<code>npu-smi info</code>命令进行查询，获取Name信息。实际配置值为AscendName，例如Name取值为xxxyy，实际配置值为Ascendxxxyy。<br><br></p><div data-filter="910b"><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品</p></div><div data-filter="310b"><p>Atlas 200I/500 A2 推理产品</p></div><div data-filter="310p"><p>Atlas 推理系列产品</p></div><div data-filter="910"><p>Atlas 训练系列产品<br><br></p></div></li></ul></div><div data-filter="A3"><ul><li>针对<term>Atlas A3 训练系列产品</term>/<term>Atlas A3 推理系列产品</term>，在安装AI处理器的服务器执行<code>npu-smi info -t board -i &lt;id&gt; -c &lt;chip_id&gt;</code>命令进行查询，获取Chip Name和NPU Name信息，实际配置值为<code>Chip Name_NPU Name</code>。例如Chip Name取值为Ascendxxx，NPU Name取值为1234，实际配置值为Ascendxxx_1234。其中：<br><code>id</code>：设备id，通过<code>npu-smi info -l</code>命令查出的NPU ID即为设备id，命令中表示为<code>&lt;id&gt;</code>。<br><code>chip_id</code>：芯片id，通过<code>npu-smi info -m</code>命令查出的Chip ID即为芯片id，命令中表示为<code>&lt;chip_id&gt;</code>。<br><br></li></ul></div><div data-filter="950"><ul><li>针对Ascend 950PR/Ascend 950DT，在安装AI处理器的服务器执行<code>npu-smi info -t board -i &lt;id&gt;</code>命令进行查询，获取Chip Name和NPU Name信息，实际配置值为<code>Chip Name_NPU Name</code>。例如Chip Name取值为Ascendxxx，NPU Name取值为1234，实际配置值为Ascendxxx_1234。<br>其中：<code>id</code>为设备id，通过<code>npu-smi info -l</code>命令查出的NPU ID即为设备id，命令中表示为<code>&lt;id&gt;</code>。</li></ul></div></div><ul><li><code>OPTIONS …</code>（必选）：传递给编译器的编译选项。</li></ul><p><strong>示例：</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_kernel_options</span><span class="p">(</span><span class="s">ascendc_kernels</span><span class="w"> </span><span class="s">ALL</span><span class="w"> </span><span class="s">OPTIONS</span><span class="w"> </span><span class="s">--save-temp-files</span><span class="w"> </span><span class="s">-g</span><span class="p">)</span><span class="w">   </span><span class="c">#为算子添加编译选项</span>
</code></pre></div><p>npu_op_kernel_options(ascendc_kernels AddCustom SOC_SERIES Ascendxxx Ascendyyy OPTIONS -DASCENDC_DEBUG)</p><h3 id="npu_op_kernel_sources">npu_op_kernel_sources<a class="header-anchor" href="#npu_op_kernel_sources">​</a></h3><p>描述核函数（Kernel）目标的源码信息，包括设置算子的核函数（Kernel）实现文件和源码路径等。</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_kernel_sources</span><span class="p">(</span><span class="s">&lt;target_name&gt;</span><span class="w"> </span><span class="s">[OP_TYPE</span><span class="w"> </span><span class="s">&lt;op_type&gt;]</span><span class="w"> </span><span class="s">[KERNEL_DIR</span><span class="w"> </span><span class="s">&lt;path&gt;]</span><span class="w"> </span><span class="s">[COMPUTE_UNIT</span><span class="w"> </span><span class="s">&lt;soc_version&gt;...</span><span class="w"> </span><span class="s">|</span><span class="w"> </span><span class="s">SOC_SERIES</span><span class="w"> </span><span class="s">&lt;series&gt;...]</span><span class="w"> </span><span class="s">[KERNEL_FILE</span><span class="w"> </span><span class="s">&lt;file&gt;]</span><span class="p">)</span>
</code></pre></div><p><strong>参数说明：</strong></p><ul><li><code>&lt;target_name&gt;</code>（必选）：目标的名称。</li><li><code>[OP_TYPE &lt;op_type&gt;]</code>（可选）：算子类型，必须与<code>KERNEL_FILE</code>同时存在。</li><li><code>[KERNEL_DIR &lt;path&gt;]</code>（可选）：指定核函数（Kernel）源码相对于<code>SRC_BASE</code>的相对路径。若算子的源码文件没有平铺在<code>SRC_BASE</code>目录（通过<code>npu_op_kernel_library</code>设置）下，可以通过<code>KERNEL_DIR</code>指定特定目录。</li><li><code>[COMPUTE_UNIT &lt;soc_version&gt;...]</code>（可选）：设置<code>KERNEL_FILE</code>在指定型号生效。默认<code>KERNEL_FILE</code>对所有型号生效。与<code>SOC_SERIES</code>不能同时使用。</li><li><code>[SOC_SERIES &lt;series&gt;...]</code>（可选）：设置<code>KERNEL_FILE</code>在指定系列生效。输入不区分大小写；与<code>COMPUTE_UNIT</code>不能同时使用，<code>SOC_SERIES</code>关键字后必须提供至少一个值；同一次调用同时提供<code>SOC_SERIES</code>和<code>COMPUTE_UNIT</code>，或只提供<code>SOC_SERIES</code>关键字不提供值，CMake配置阶段会报错。</li><li><code>[KERNEL_FILE &lt;file&gt;]</code>（可选）：指定算子入口的核函数（Kernel）实现文件名。若算子的核函数（Kernel）实现cpp文件需要自定义命名，需同时指定<code>OP_TYPE</code>（算子类型）和<code>KERNEL_FILE</code>（核函数（Kernel）实现cpp文件名），以配置两者之间的对应关系。不配置时，核函数（Kernel）实现cpp文件名和OpType之间需满足转换规则，参考<a href="./naming_conversion_table.html">命名转换规则对照表</a>。</li></ul><p><strong>示例：</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_kernel_sources</span><span class="p">(</span><span class="s">ascendc_kernels</span>
<span class="w">    </span><span class="s">OP_TYPE</span><span class="w"> </span><span class="s">AddCustom</span>
<span class="w">    </span><span class="s">KERNEL_DIR</span><span class="w"> </span><span class="s">./Add</span>
<span class="w">    </span><span class="s">COMPUTE_UNIT</span><span class="w"> </span><span class="s">Ascendxxxyy</span>
<span class="w">    </span><span class="s">KERNEL_FILE</span><span class="w"> </span><span class="s">add_custom.cpp</span>
<span class="p">)</span>
</code></pre></div><p>也可以使用<code>SOC_SERIES</code>按系列指定：</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_kernel_sources</span><span class="p">(</span><span class="s">ascendc_kernels</span>
<span class="w">    </span><span class="s">OP_TYPE</span><span class="w"> </span><span class="s">AddCustom</span>
<span class="w">    </span><span class="s">KERNEL_DIR</span><span class="w"> </span><span class="s">./Add</span>
<span class="w">    </span><span class="s">SOC_SERIES</span><span class="w"> </span><span class="s">Ascendxxx</span>
<span class="w">    </span><span class="s">KERNEL_FILE</span><span class="w"> </span><span class="s">add_custom.cpp</span>
<span class="p">)</span>
</code></pre></div><h3 id="npu_op_device_tiling_library">npu_op_device_tiling_library<a class="header-anchor" href="#npu_op_device_tiling_library">​</a></h3><p>创建Device侧Tiling库。使用该选项时，package的类型仅支持配置为RUN（run包模式）。</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_device_tiling_library</span><span class="p">(</span><span class="s">&lt;target_name&gt;</span><span class="w"> </span><span class="s">&lt;type&gt;</span><span class="w"> </span><span class="s">&lt;files&gt;</span><span class="p">)</span>
</code></pre></div><p><strong>参数说明：</strong></p><ul><li><code>&lt;target_name&gt;</code>（必选）：目标的名称。</li><li><code>&lt;type&gt;</code>（必选）：指定Tiling产物的类型。支持取值为<code>SHARED</code>、<code>STATIC</code>。</li><li><code>&lt;files&gt;</code>（必选）：指定Tiling源码文件。</li></ul><p><strong>示例：</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_device_tiling_library</span><span class="p">(</span><span class="s">device_tiling</span><span class="w"> </span><span class="s">SHARED</span>
<span class="w">    </span><span class="s">device_tiling_impl.cpp</span>
<span class="p">)</span>
</code></pre></div><hr><h2 id="其他">其他<a class="header-anchor" href="#其他">​</a></h2><h3 id="npu_op_code_gen">npu_op_code_gen<a class="header-anchor" href="#npu_op_code_gen">​</a></h3><p>执行代码生成过程，生成aclnn单算子调用代码和入图所需的原型定义代码。</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_code_gen</span><span class="p">(</span><span class="s">SRC</span><span class="w"> </span><span class="s">&lt;src_files&gt;</span><span class="w"> </span><span class="s">OUT_DIR</span><span class="w"> </span><span class="s">&lt;output_dir&gt;</span><span class="w"> </span><span class="s">PACKAGE</span><span class="w"> </span><span class="s">&lt;pkg_name&gt;</span><span class="w"> </span><span class="s">[COMPILE_OPTIONS</span><span class="w"> </span><span class="s">...]</span><span class="w"> </span><span class="s">[JOIN_OP_DEF</span><span class="w"> </span><span class="s">...]</span><span class="p">)</span>
</code></pre></div><p><strong>参数说明：</strong></p><ul><li><code>SRC &lt;src_files&gt;</code>（必选）：参与代码生成的源文件范围。</li><li><code>OUT_DIR &lt;output_dir&gt;</code>（必选）：生成代码的输出路径。</li><li><code>PACKAGE &lt;pkg_name&gt;</code>（必选）：指定生成代码的package名称。</li><li><code>[COMPILE_OPTIONS ...]</code>（可选）：自定义编译过程中的编译选项。</li><li><code>[JOIN_OP_DEF ...]</code>（可选）：默认为False。设置为False，编译CMakePreset.json中设置的AI处理器型号对应的算子；设置成True，则编译CMakePreset.json和算子原型注册中共有的AI处理器型号对应的算子。</li></ul><p><strong>示例：</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">aux_source_directory</span><span class="p">(</span><span class="o">\${</span><span class="nv">CMAKE_CURRENT_SOURCE_DIR</span><span class="o">}</span><span class="w"> </span><span class="s">ops_srcs</span><span class="p">)</span>
<span class="nb">npu_op_code_gen</span><span class="p">(</span>
<span class="w">    </span><span class="s">SRC</span><span class="w"> </span><span class="o">\${</span><span class="nv">ops_srcs</span><span class="o">}</span>
<span class="w">    </span><span class="s">PACKAGE</span><span class="w"> </span><span class="o">\${</span><span class="nv">package_name</span><span class="o">}</span>
<span class="w">    </span><span class="s">COMPILE_OPTIONS</span><span class="w"> </span><span class="s">-g</span>
<span class="w">    </span><span class="s">OUT_DIR</span><span class="w"> </span><span class="o">\${</span><span class="nv">ASCEND_AUTOGEN_PATH</span><span class="o">}</span>
<span class="w">    </span><span class="s">JOIN_OP_DEF</span><span class="w"> </span><span class="s">False</span>
<span class="p">)</span>
</code></pre></div><hr><h2 id="相关文档">相关文档<a class="header-anchor" href="#相关文档">​</a></h2><ul><li><a href="../compilation_and_deployment/basic_process.html#advanced-build-organization">算子工程编译拓展</a> — 完整的CMakeLists.txt编写方法与编译命令说明。</li><li><a href="../design_and_implementation/operator_prototype_definition.html">算子原型定义</a> — 核函数（Kernel）实现文件名与OpType的转换规则。</li><li><a href="../../../appendix/common_operations/how_to_use_workspace.html">如何使用workspace</a> — Tiling函数中workspace的设置方法。</li></ul></article></div>`,1)])])}const g=a(l,[["render",e]]);export{h as __pageData,g as default};
